@startuml

class Sober {
}

class Car {
  + LicensePlate : string
}

class Owner {
  + Name : string
}

class Accident {
  + Date : date
  + Location : string
  + DamageAmount : float
}

class RideHailService {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : float
  + NumberOfPassengers : int
  + Fee : float
  + RequestType : string
}

class RideShareService {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : float
  + NumberOfPassengers : int
  + UpfrontNegotiatedFee : float
}

class Customer {
  + Name : string
}

class RideHailCustomer {
  + Name : string
}

class RideShareCustomer {
  + Name : string
}

Car "0..*" -- "0..1" Owner : owned by
Car "1" -- "0..*" Accident : involved in
Car "1" -- "0..*" RideHailService : provides
Car "1" -- "0..*" RideShareService : provides

RideHailService "0..*" -- "1" RideHailCustomer : lead customer
RideHailService "0..*" -- "1..6" Customer : passenger

RideShareService "0..*" -- "1..10" Customer : passenger

Sober "1" -- "0..*" Car : operates
Sober "1" -- "0..*" RideHailService : offers
Sober "1" -- "0..*" RideShareService : offers

@enduml

